/// sin(2 pi x) for x in [0, 1] turns, factored Chebyshev degree 13.
template<typename T>
inline auto cheb_turns_sin_13(T x) -> T
{
    const auto u = x - T(0.5);
    const auto u2 = u * u;
    auto p = T(3.161601856720294);
    p = p * u2 + T(-14.049663725541881);
    p = p * u2 + T(38.49587885367295);
    p = p * u2 + T(-67.07662737709583);
    p = p * u2 + T(64.83582285642966);
    p = p * u2 + T(-25.132741155387375);
    return -u * x * (x - T(1)) * p;
}
